UPDATE trade_pay_notify_task SET notify_times=notify_times+1, last_execute_time=#{now}, update_time=#{now}
WHERE id=#{id} AND status IN ('PENDING','FAILED') AND notify_times=#{expectedTimes}
AND notify_times < max_notify_times AND (lease_until IS NULL OR lease_until <= #{now})

UPDATE trade_pay_notify_task SET notify_times=notify_times+1, execute_version=execute_version+1,
    lease_until=#{until}, last_execute_time=#{now}, update_time=#{now}
WHERE id=#{id} AND status IN ('PENDING','FAILED') AND notify_times=#{expectedTimes}
    AND execute_version=#{version} AND notify_times < max_notify_times
    AND (lease_until IS NULL OR lease_until <= #{now})

UPDATE trade_pay_notify_task SET status=#{status},last_response=#{response},next_notify_time=#{next},
    lease_until=NULL,update_time=#{now}
WHERE id=#{id} AND execute_version=#{version} AND status IN ('PENDING','FAILED')

UPDATE trade_pay_notify_task SET status='PENDING',notify_times=0,execute_version=execute_version+1,
    lease_until=NULL,next_notify_time=#{now},last_response=NULL,update_time=#{now}
WHERE id=#{id} AND status<>'SUCCESS' AND (lease_until IS NULL OR lease_until <= #{now})

mapper.select:
SELECT * FROM trade_pay_notify_task WHERE status IN ('PENDING','FAILED')
    AND notify_times < max_notify_times AND (next_notify_time IS NULL OR next_notify_time <= #{now})
    AND (lease_until IS NULL OR lease_until <= #{now}) ORDER BY id LIMIT #{limit}
